            font-weight: 600;
        }}

        .badge-positive {{
            background: rgba(0, 208, 156, 0.15);
            color: #00a378;
        }}

        .badge-negative {{
            background: rgba(255, 107, 107, 0.15);
            color: #d63031;
        }}

        .badge-neutral {{
            background: rgba(108, 117, 125, 0.15);
            color: var(--neutral);
        }}

        .insight-box {{
            background: linear-gradient(135deg, #f8f9fa 0%, #e9ecef 100%);
            padding: 20px;
            border-radius: 8px;
            border-left: 4px solid var(--accent);
            margin: 15px 0;
        }}

        .two-col {{
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 30px;
        }}

        @media (max-width: 768px) {{
            .two-col {{ grid-template-columns: 1fr; }}
            .kpi-dashboard {{ grid-template-columns: repeat(2, 1fr); }}
        }}

        .toc {{
            background: #f8f9fa;
            padding: 25px;
            border-radius: 8px;
            margin-bottom: 30px;
        }}

        .toc ul {{
            list-style: none;
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
            gap: 10px;
        }}

        .toc a {{
            color: var(--accent);
            text-decoration: none;
            padding: 8px 12px;
            display: block;
            border-radius: 4px;
            transition: background 0.2s;
        }}

        .toc a:hover {{
            background: rgba(15, 52, 96, 0.1);
        }}

        footer {{
            text-align: center;
            padding: 40px;
            color: var(--neutral);
            font-size: 0.85rem;
        }}

        .phase-tag {{
            display: inline-block;
            padding: 4px 10px;
            border-radius: 4px;
            font-size: 0.75rem;
            font-weight: 600;
            margin-left: 8px;
        }}

        .phase-bull {{ background: rgba(0, 208, 156, 0.15); color: #00a378; }}
        .phase-bear {{ background: rgba(255, 107, 107, 0.15); color: #d63031; }}
    '''
html_content += '''
    </style>
</head>
<body>
    <div class="container">
        <header>
            <h1>Nike Inc. (NKE)</h1>
            <div class="subtitle">Historical Stock Performance Analysis</div>
            <div class="date-range">January 3, 2000 — ''' + df['Date'].max().strftime('%B %d, %Y') + '''</div>
        </header>

        <div class="toc">
            <strong>Report Sections</strong>
            <ul>
                <li><a href="#executive-summary">Executive Summary</a></li>
                <li><a href="#price-trend">Long-Term Price Trend Analysis</a></li>
                <li><a href="#volatility">Volatility and Risk Assessment</a></li>
                <li><a href="#volume">Trading Volume Patterns</a></li>
                <li><a href="#annual">Annual Performance Breakdown</a></li>
                <li><a href="#takeaways">Key Takeaways</a></li>
            </ul>
