#!/usr/bin/env python3
"""
Nike Inc. (NKE) Historical Stock Performance Analysis Report Generator
"""

import pandas as pd
import numpy as np
from datetime import datetime
import os

# Read and parse data
df = pd.read_csv('/app/benchmark/data.csv')
df['Date'] = pd.to_datetime(df['Date'], format='%m/%d/%Y')
df = df.sort_values('Date').reset_index(drop=True)

# Basic stats
print(f"Dataset: {len(df)} rows from {df['Date'].min().strftime('%Y-%m-%d')} to {df['Date'].max().strftime('%Y-%m-%d')}")
print(f"Close price range: ${df['Close'].min():.2f} - ${df['Close'].max():.2f}")

# Calculate daily returns
df['Daily_Return'] = df['Close'].pct_change()
df['Daily_Range'] = df['High'] - df['Low']

# === KPI Calculations ===

# 1. Cumulative Return
first_close = df['Close'].iloc[0]
last_close = df['Close'].iloc[-1]
cumulative_return = ((last_close / first_close) - 1) * 100
print(f"Cumulative Return: {cumulative_return:.2f}%")

# 2. CAGR
years = (df['Date'].iloc[-1] - df['Date'].iloc[0]).days / 365.25
cagr = ((last_close / first_close) ** (1/years) - 1) * 100
print(f"CAGR: {cagr:.2f}%")

# 3. Maximum Drawdown
rolling_max = df['Close'].cummax()
drawdown = (df['Close'] - rolling_max) / rolling_max * 100
max_drawdown = drawdown.min()
print(f"Maximum Drawdown: {max_drawdown:.2f}%")

# 4. Average Daily Trading Volume
avg_volume = df['Volume'].mean()
print(f"Average Daily Volume: {avg_volume:,.0f}")

# 5. Annualized Volatility
daily_volatility = df['Daily_Return'].std()
annualized_volatility = daily_volatility * np.sqrt(252) * 100
print(f"Annualized Volatility: {annualized_volatility:.2f}%")

# === Yearly Analysis ===
df['Year'] = df['Date'].dt.year
yearly_stats = df.groupby('Year').agg({
    'Close': ['first', 'last', 'min', 'max'],
    'Volume': 'mean',
    'Daily_Return': 'std',
    'Daily_Range': 'mean'
}).round(4)
yearly_stats.columns = ['Open', 'Close', 'Low', 'High', 'Avg_Volume', 'Volatility', 'Avg_Daily_Range']
yearly_stats['Annual_Return'] = ((yearly_stats['Close'] / yearly_stats['Open']) - 1) * 100
yearly_stats['Annual_Volatility'] = yearly_stats['Volatility'] * np.sqrt(252) * 100

# === Decade Analysis ===
def get_decade(year):
    return f"{(year // 10) * 10}s"

df['Decade'] = df['Year'].apply(get_decade)
decade_stats = df.groupby('Decade').agg({
    'Close': ['first', 'last'],
    'Volume': 'mean',
    'Daily_Return': 'std'
}).round(4)
decade_stats.columns = ['Start_Close', 'End_Close', 'Avg_Volume', 'Daily_Volatility']
decade_stats['Decade_Return'] = ((decade_stats['End_Close'] / decade_stats['Start_Close']) - 1) * 100
decade_stats['Annualized_Volatility'] = decade_stats['Daily_Volatility'] * np.sqrt(252) * 100

# === Rolling Metrics ===
# 30-day rolling volatility
df['Rolling_Vol_30'] = df['Daily_Return'].rolling(30).std() * np.sqrt(252) * 100
# 252-day (1-year) rolling volatility
df['Rolling_Vol_252'] = df['Daily_Return'].rolling(252).std() * np.sqrt(252) * 100

# === Identify Key Phases ===
# Find ATH and ATL
ath_idx = df['Close'].idxmax()
atl_idx = df['Close'].idxmin()
ath_date = df.loc[ath_idx, 'Date']
ath_price = df.loc[ath_idx, 'Close']
atl_date = df.loc[atl_idx, 'Date']
atl_price = df.loc[atl_idx, 'Close']

print(f"ATH: {ath_date.strftime('%Y-%m-%d')} @ ${ath_price:.2f}")
print(f"ATL: {atl_date.strftime('%Y-%m-%d')} @ ${atl_price:.2f}")

# Major market events correlation
events = {
    '2000-2002': 'Dot-com Bust',
    '2008-2009': 'Global Financial Crisis',
    '2011': 'Debt Ceiling Crisis',
    '2015-2016': 'China Slowdown / Oil Crash',
    '2020': 'COVID-19 Pandemic',
    '2022': 'Inflation / Rate Hikes'
}

# Volume spike analysis (> 2x average)
volume_threshold = avg_volume * 2
volume_spikes = df[df['Volume'] > volume_threshold][['Date', 'Close', 'Volume']].copy()
volume_spikes['Volume_Multiple'] = volume_spikes['Volume'] / avg_volume

print(f"Volume spikes (>2x avg): {len(volume_spikes)} days")

# === Chart Data Preparation ===
# For price chart - sample to reduce size while maintaining shape
price_chart_data = df[['Date', 'Close']].copy()
# Sample every 5th row for the chart
price_sample = price_chart_data.iloc[::5].to_dict('records')
price_chart_json = str([{'x': r['Date'].strftime('%Y-%m-%d'), 'y': round(r['Close'], 2)} for r in price_sample]).replace("'", '"')

# Volume chart data
volume_chart_data = df[['Date', 'Volume']].iloc[::5].to_dict('records')
volume_chart_json = str([{'x': r['Date'].strftime('%Y-%m-%d'), 'y': r['Volume']} for r in volume_chart_data]).replace("'", '"')

# Volatility chart data
vol_chart_data = df[['Date', 'Rolling_Vol_30', 'Rolling_Vol_252']].dropna().iloc[::5].to_dict('records')
vol_chart_json = str([{'x': r['Date'].strftime('%Y-%m-%d'), 'y30': round(r['Rolling_Vol_30'], 2), 'y252': round(r['Rolling_Vol_252'], 2)} for r in vol_chart_data]).replace("'", '"')

# Annual returns bar chart
annual_returns = yearly_stats['Annual_Return'].dropna().to_dict()
annual_returns_json = str(annual_returns).replace("'", '"')

# Drawdown chart
drawdown_data = df[['Date', 'Close']].copy()
drawdown_data['Drawdown'] = drawdown
drawdown_sample = drawdown_data.iloc[::10].to_dict('records')
drawdown_chart_json = str([{'x': r['Date'].strftime('%Y-%m-%d'), 'y': round(r['Drawdown'], 2)} for r in drawdown_sample]).replace("'", '"')

# === Year-by-Year High/Low for table ===
yearly_table_data = []
for year in sorted(df['Year'].unique()):
    year_df = df[df['Year'] == year]
    start_close = year_df['Close'].iloc[0]
    end_close = year_df['Close'].iloc[-1]
