import pandas as pd
import numpy as np
from datetime import datetime
import os

# Read and parse data
df = pd.read_csv('/app/benchmark/data.csv')
df['Date'] = pd.to_datetime(df['Date'], format='%m/%d/%Y')
df = df.sort_values('Date').reset_index(drop=True)

# Basic stats
print(f"Dataset: {len(df)} rows from {df['Date'].min().strftime('%Y-%m-%d')} to {df['Date'].max().strftime('%Y-%m-%d')}")
print(f"Close price range: ${df['Close'].min():.2f} - ${df['Close'].max():.2f}")

# Calculate daily returns
df['Daily_Return'] = df['Close'].pct_change()
df['Daily_Range'] = df['High'] - df['Low']

# === KPI Calculations ===

# 1. Cumulative Return
first_close = df['Close'].iloc[0]
last_close = df['Close'].iloc[-1]
cumulative_return = ((last_close / first_close) - 1) * 100
print(f"Cumulative Return: {cumulative_return:.2f}%")

# 2. CAGR
years = (df['Date'].iloc[-1] - df['Date'].iloc[0]).days / 365.25
cagr = ((last_close / first_close) ** (1/years) - 1) * 100
print(f"CAGR: {cagr:.2f}%")

# 3. Maximum Drawdown
rolling_max = df['Close'].cummax()
drawdown = (df['Close'] - rolling_max) / rolling_max * 100
max_drawdown = drawdown.min()
print(f"Maximum Drawdown: {max_drawdown:.2f}%")

# 4. Average Daily Trading Volume
avg_volume = df['Volume'].mean()
print(f"Average Daily Volume: {avg_volume:,.0f}")

# 5. Annualized Volatility
daily_volatility = df['Daily_Return'].std()
annualized_volatility = daily_volatility * np.sqrt(252) * 100
print(f"Annualized Volatility: {annualized_volatility:.2f}%")

# === Yearly Analysis ===
df['Year'] = df['Date'].dt.year
yearly_stats = df.groupby('Year').agg({
    'Close': ['first', 'last', 'min', 'max'],
    'Volume': 'mean',
    'Daily_Return': 'std',
    'Daily_Range': 'mean'
}).round(4)
yearly_stats.columns = ['Open', 'Close', 'Low', 'High', 'Avg_Volume', 'Volatility', 'Avg_Daily_Range']
yearly_stats['Annual_Return'] = ((yearly_stats['Close'] / yearly_stats['Open']) - 1) * 100
yearly_stats['Annual_Volatility'] = yearly_stats['Volatility'] * np.sqrt(252) * 100

# === Decade Analysis ===
def get_decade(year):
    return f"{(year // 10) * 10}s"

df['Decade'] = df['Year'].apply(get_decade)
decade_stats = df.groupby('Decade').agg({
    'Close': ['first', 'last'],
    'Volume': 'mean',
    'Daily_Return': 'std'
}).round(4)
decade_stats.columns = ['Start_Close', 'End_Close', 'Avg_Volume', 'Daily_Volatility']
